import express from 'express';
import { query, isPostgres } from '../db.js';
import { verifyAdminToken } from '../middleware/auth.js';

const router = express.Router();

// Parameter Mapping Labels
export const PARAMETERS = {
  // Quality of Teaching
  'q1_on_time_completion': '1. On time completion of course',
  'q2_faculty_knowledge': '2. FACULTY KNOWLEDGE OF THE SUBJECT',
  'q3_response_to_questions': '3. RESPONSE OF FACULTY TO THE QUESTIONS',
  'q4_regularity': '4. Regularity in Class',
  'q5_interest_generated': '5. INTEREST GENERATED BY TEACHER',
  // Courses
  'q6_content_clarity': '1. CLARITY OF COURSE CONTENT',
  'q7_module_coverage': '2. COVERAGE OF MODULE',
  'q8_resources_guidance': '3. GUIDANCE TO RELEVANT RESOURCES & TECHNOLOGY',
  'q9_practical_examples': '4. CASE STUDIES & PRACTICAL EXAMPLES'
};

// 1. Student Anonymous Feedback Submission (Enforces Valid Timed Passcode)
router.post('/submit', async (req, res) => {
  try {
    const { semester, passcode, ratings, qualitative, remarks } = req.body;

    if (!semester || !ratings || typeof ratings !== 'object') {
      return res.status(400).json({ message: 'Invalid feedback data payload.' });
    }

    if (!passcode) {
      return res.status(400).json({ message: 'Session Passcode is required to submit feedback.' });
    }

    // Verify passcode & validity timer
    const cleanPasscode = passcode.trim().toUpperCase();
    const tokenCheck = await query('SELECT * FROM student_tokens WHERE passcode = $1', [cleanPasscode]);

    if (!tokenCheck || tokenCheck.length === 0) {
      return res.status(404).json({ message: 'Invalid Feedback Session Passcode.' });
    }

    const tok = tokenCheck[0];
    const now = Date.now();
    const expiresAtTime = new Date(tok.expires_at).getTime();

    if (now > expiresAtTime) {
      return res.status(403).json({ message: '⏰ This feedback session passcode has EXPIRED! Submissions are now closed.' });
    }

    // Insert anonymous submission header
    const subRes = await query(
      'INSERT INTO feedback_submissions (semester) VALUES ($1) RETURNING id',
      [parseInt(semester)]
    );
    const submissionId = subRes && subRes[0] ? subRes[0].id : 1;

    // Insert ratings
    for (const subjectIdStr of Object.keys(ratings)) {
      const subjectId = parseInt(subjectIdStr);
      const subjRatings = ratings[subjectIdStr];

      for (const criterionKey of Object.keys(subjRatings)) {
        const ratingVal = parseInt(subjRatings[criterionKey]);
        if (ratingVal >= 1 && ratingVal <= 5) {
          await query(
            'INSERT INTO feedback_ratings (submission_id, subject_id, criterion_key, rating) VALUES ($1, $2, $3, $4)',
            [submissionId, subjectId, criterionKey, ratingVal]
          );
        }
      }
    }

    // Insert qualitative feedback per faculty
    if (qualitative && typeof qualitative === 'object') {
      for (const facultyIdStr of Object.keys(qualitative)) {
        const facultyId = parseInt(facultyIdStr);
        const item = qualitative[facultyIdStr];
        await query(
          'INSERT INTO faculty_qualitative (submission_id, faculty_id, take_another_course, satisfied_learning, satisfied_mentoring, remarks) VALUES ($1, $2, $3, $4, $5, $6)',
          [submissionId, facultyId, !!item.take_another_course, !!item.satisfied_learning, !!item.satisfied_mentoring, remarks || '']
        );
      }
    }

    res.status(201).json({ message: 'Thank you! Your feedback has been submitted anonymously.' });
  } catch (err) {
    console.error('Error submitting feedback:', err);
    res.status(500).json({ message: 'Error submitting feedback.' });
  }
});

// 2. Admin: Consolidated Evaluation Report (With Mode Calculation & Ratings Breakdown)
router.get('/report', verifyAdminToken, async (req, res) => {
  try {
    const semester = parseInt(req.query.semester || 1);

    const subjects = await query(
      `SELECT s.*, f.name as faculty_name, f.faculty_code 
       FROM subjects s 
       LEFT JOIN faculties f ON s.faculty_id = f.id 
       WHERE s.semester = $1 
       ORDER BY s.subject_code ASC`,
      [semester]
    );

    const totalSubmissionsRes = await query(
      `SELECT COUNT(*) as count FROM feedback_submissions WHERE semester = $1`,
      [semester]
    );
    const totalSubmissions = parseInt(totalSubmissionsRes[0]?.count || 0);

    let reportData = {};
    for (const subj of subjects) {
      const stats = await query(
        `SELECT 
          criterion_key,
          COUNT(CASE WHEN rating = 5 THEN 1 END) AS count_5,
          COUNT(CASE WHEN rating = 4 THEN 1 END) AS count_4,
          COUNT(CASE WHEN rating = 3 THEN 1 END) AS count_3,
          COUNT(CASE WHEN rating = 2 THEN 1 END) AS count_2,
          COUNT(CASE WHEN rating = 1 THEN 1 END) AS count_1,
          COUNT(rating) AS total_responses,
          AVG(rating) AS average_rating
        FROM feedback_ratings
        WHERE subject_id = $1
        GROUP BY criterion_key`,
        [subj.id]
      );

      const criteriaReport = {};
      for (const stat of stats) {
        const counts = [
          { val: 5, count: parseInt(stat.count_5 || 0) },
          { val: 4, count: parseInt(stat.count_4 || 0) },
          { val: 3, count: parseInt(stat.count_3 || 0) },
          { val: 2, count: parseInt(stat.count_2 || 0) },
          { val: 1, count: parseInt(stat.count_1 || 0) },
        ];
        
        counts.sort((a, b) => b.count - a.count || b.val - a.val);
        const modeRating = counts[0].count > 0 ? counts[0].val : 0;

        criteriaReport[stat.criterion_key] = {
          count_5: parseInt(stat.count_5 || 0),
          count_4: parseInt(stat.count_4 || 0),
          count_3: parseInt(stat.count_3 || 0),
          count_2: parseInt(stat.count_2 || 0),
          count_1: parseInt(stat.count_1 || 0),
          total_responses: parseInt(stat.total_responses || 0),
          average_rating: parseFloat(stat.average_rating || 0).toFixed(2),
          mode_rating: modeRating
        };
      }

      const qualitativeStats = await query(
        `SELECT 
          COUNT(CASE WHEN take_another_course = true THEN 1 END) as count_take_again,
          COUNT(CASE WHEN satisfied_learning = true THEN 1 END) as count_learning,
          COUNT(CASE WHEN satisfied_mentoring = true THEN 1 END) as count_mentoring,
          COUNT(*) as total_qualitative
         FROM faculty_qualitative
         WHERE faculty_id = $1`,
        [subj.faculty_id]
      );

      const remarksRes = await query(
        `SELECT remarks FROM faculty_qualitative WHERE faculty_id = $1 AND remarks IS NOT NULL AND remarks != '' LIMIT 10`,
        [subj.faculty_id]
      );

      reportData[subj.id] = {
        subject_id: subj.id,
        subject_code: subj.subject_code,
        subject_name: subj.subject_name,
        faculty_name: subj.faculty_name,
        faculty_code: subj.faculty_code,
        criteria: criteriaReport,
        qualitative: qualitativeStats[0] || {},
        remarks: remarksRes.map(r => r.remarks)
      };
    }

    res.json({
      semester,
      totalSubmissions,
      parameterLabels: PARAMETERS,
      subjects,
      reportData
    });

  } catch (err) {
    console.error('Error generating report:', err);
    res.status(500).json({ message: 'Error generating consolidated report.' });
  }
});

export default router;
